func:
// TASK SETTINGS of the PBI report build: folders, sites, months, dry run.
// In: msg.payload = the job {tables, sites, from, to}; all optional (months
// YYYY-MM, default last month and this month). Out: msg.job, settings stored.

// Folders in the data lake, without a leading slash.
var IN_REFERENCE = 'eu_report/reference';
var IN_SOURCE = 'eu_report/pbi_report/source';
var OUT_ROOT = 'eu_report/pbi_report/report';
// Sites that have files in the data lake.
var ALL_SITES = [
  'Hull',
  'Nottingham',
  'Weinheim'
];
var DRY_RUN = {
  pbi_machine_names: true,
  pbi_shift_naming: true,
  pbi_calendar: true,
  pbi_plan_opt: true,
  pbi_time_utilisation: true,
  pbi_daily_losses: true
};
// First and last date of the calendar table (the report uses 2011 to 2050).
var CALENDAR_START = '2011-01-01';
var CALENDAR_END = '2050-12-31';

var shared = glob.get('cfg');
if (!shared) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: 'CONFIG not run'
  });
  node.error('global cfg is missing: deploy or run the Config tab first');
  return null;
}

function fail(text) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: text
  });
  node.error(text);
  return null;
}

// Months from the first to the last one, both as YYYY-MM.
function monthList(from, to) {
  var out = [];
  var year = Number(from.slice(0, 4));
  var month = Number(from.slice(5, 7));
  var last = Number(to.slice(0, 4)) * 12 + Number(to.slice(5, 7));
  while (year * 12 + month <= last) {
    out.push(year + '-' + (month < 10 ? '0' + month : month));
    month++;
    if (month > 12) {
      month = 1;
      year++;
    }
  }
  return out;
}

var asked = msg.payload && typeof msg.payload === 'object' ? msg.payload : {};
var allTables = Object.keys(DRY_RUN);
var tables = Array.isArray(asked.tables) ? asked.tables : allTables;
var sites = Array.isArray(asked.sites) ? asked.sites : ALL_SITES;
var unknown = tables.filter(function (t) {
  return allTables.indexOf(t) === -1;
}).concat(sites.filter(function (s) {
  return ALL_SITES.indexOf(s) === -1;
}));
if (unknown.length) {
  return fail('unknown table or site in the job: ' + unknown.join(', '));
}

var now = new Date();
var thisMonth = now.toISOString().slice(0, 7);
var lastMonth = new Date(
  Date.UTC(now.getUTCFullYear(), now.getUTCMonth() - 1, 1)
);
var from = asked.from || lastMonth.toISOString().slice(0, 7);
var to = asked.to || thisMonth;
if (!/^\d{4}-\d{2}$/.test(from) || !/^\d{4}-\d{2}$/.test(to) || from > to) {
  return fail('from and to must be months YYYY-MM, from not after to');
}

var cfg = Object.assign({}, shared);
cfg.dryRun = DRY_RUN;
cfg.referenceFolder = IN_REFERENCE;
cfg.sourceFolder = IN_SOURCE;
cfg.outRoot = OUT_ROOT;
cfg.calendarStart = CALENDAR_START;
cfg.calendarEnd = CALENDAR_END;
cfg.paths = {};
allTables.forEach(function (table) {
  cfg.paths[table] = OUT_ROOT + '/' + table + '/' + table + '.parquet';
});
flow.set('cfg', cfg);

msg.job = {
  tables: tables,
  sites: sites,
  months: monthList(from, to)
};
var writing = tables.filter(function (table) {
  return !DRY_RUN[table];
});
node.status({
  fill: writing.length ? 'green' : 'yellow',
  shape: 'dot',
  text: writing.length ? writing.length + ' table(s) WRITE' : 'DRY RUN'
});
return msg;

// Starts the jobs of the run. In: msg.job {tables, sites, months}. Out 1:
// machine names (site list, a split follows). Out 2: shift names. Out 3:
// calendar. Out 4: the site setup for plan OPT, time utilisation and daily
// losses. A table that is not in the job gets no message.
var job = msg.job;
var day = new Date().toISOString().slice(0, 10);
var loadedAt = Date.now();

function wants(table) {
  return job.tables.indexOf(table) !== -1;
}

function start(wanted, payload) {
  if (!wanted) {
    return null;
  }
  return {
    payload: payload,
    job: job,
    day: day,
    mode: 'report',
    loadedAt: loadedAt
  };
}

node.status({
  fill: 'green',
  shape: 'dot',
  text: job.tables.length + ' table(s), ' + job.sites.length + ' site(s)'
});
return [
  start(wants('pbi_machine_names'), job.sites),
  start(wants('pbi_shift_naming'), []),
  start(wants('pbi_calendar'), []),
  start(wants('pbi_plan_opt') || wants('pbi_time_utilisation') ||
    wants('pbi_daily_losses'), job.sites)
];

// Sets the folder of one site for the list objects node.
// In: msg.payload = one site name (after the split). Out: msg.site, msg.what
// and msg.path = the reference folder of the site, ending with a slash.
var TYPE_FOLDER = 'machine_names';
var cfg = flow.get('cfg');

msg.site = msg.payload;
msg.what = 'machine names';
msg.path = cfg.referenceFolder + '/' + TYPE_FOLDER;
msg.path += '/site=' + msg.site + '/';
return msg;

// Picks the newest .csv of the folder list (list objects).
// Out 1: msg.path for the read node, without data/ten=<tenant>/ or a leading
// slash. Out 2: a failed item when the folder has no .csv.
var TENANT_PREFIX = /^\/?(data\/ten=[^\/]+\/)?/;
var items = Array.isArray(msg.payload) ? msg.payload : [];
var files = items.filter(function (item) {
  return /\.csv$/i.test(item.key);
});

if (!files.length) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: 'no csv file for ' + msg.site
  });
  msg.payload = {
    name: msg.site,
    failed: msg.what + ' ' + msg.site + ': no csv file in ' + msg.path,
    skipped: null,
    rows: []
  };
  return [null, msg];
}

files.sort(function (a, b) {
  return String(b.lastModified).localeCompare(String(a.lastModified));
});
msg.path = String(files[0].key).replace(TENANT_PREFIX, '');
node.status({
  fill: 'green',
  shape: 'dot',
  text: msg.path.slice(-40)
});
return [msg, null];

// Builds the machine rows of one site from its Machine Names file.
// In: msg.payload = the parsed rows (MachineName, Dept, Area, Product Type).
// Out: msg.payload = an item {name, failed, skipped, rows} for the join.
// The rules are those of the load queries of the report (Machine Names H, N).
var RULES = {
  Hull: {
    dropNames: [
      'GT4 - Auto'
    ],
    keepDepts: [
      'Dries Pack',
      'Liquids Pack'
    ]
  },
  Nottingham: {
    keepAreas: [
      'SD Packing',
      'Strepsils Packing'
    ]
  },
  Weinheim: {},
  Mira: {}
};

var site = msg.site;
var rule = RULES[site] || {};
var item = {
  name: site,
  failed: null,
  skipped: null,
  rows: []
};
var rows = Array.isArray(msg.payload) ? msg.payload : [];
if (!rows.length || rows[0].MachineName === undefined) {
  item.failed = 'machine names ' + site + ': no MachineName column or rows';
  msg.payload = item;
  return msg;
}

function text(value) {
  return value === undefined || value === null ? '' : String(value).trim();
}

function allowed(list, value) {
  return !list || list.indexOf(value) !== -1;
}

var dropped = 0;
rows.forEach(function (row) {
  var name = text(row.MachineName);
  var dept = text(row.Dept);
  var area = text(row.Area);
  var drop = !name ||
    (rule.dropNames && rule.dropNames.indexOf(name) !== -1) ||
    !allowed(rule.keepDepts, dept) ||
    !allowed(rule.keepAreas, area);
  if (drop) {
    dropped++;
    return;
  }
  item.rows.push({
    site_name: site,
    area: area,
    dept: dept,
    machine_name: name,
    product_type: text(row['Product Type']),
    unique_machine_name: name + '-' + site,
    loaded_at: msg.loadedAt
  });
});
if (dropped) {
  item.skipped = site + ': ' + dropped + ' row(s) left out by the report rules';
}
msg.payload = item;
return msg;

// Collects the items that the join delivered into one list of rows.
// In: msg.payload = array of items {name, failed, skipped, rows}.
// Out: msg.rows, msg.failed and msg.skipped (lists), msg.itemCount.
var items = Array.isArray(msg.payload) ? msg.payload : [msg.payload];
var rows = [];
var failed = [];
var skipped = (msg.planSkipped || []).slice();

items.forEach(function (item) {
  if (!item) {
    return;
  }
  if (item.failed) {
    failed.push(item.failed);
  }
  if (item.skipped) {
    skipped.push(item.skipped);
  }
  rows = rows.concat(item.rows || []);
});
msg.rows = rows;
msg.failed = failed;
msg.skipped = skipped;
msg.itemCount = items.length;
delete msg.payload;
return msg;

// Decides what happens with the table pbi_machine_names.
// In: msg.rows, msg.failed, msg.skipped. Out 1: msg.payload = rows for the
// parquet node. Out 2: a log line. A failed item means nothing is written.
var TABLE = 'pbi_machine_names';
var cfg = flow.get('cfg');
var rows = msg.rows;
var tail = '';
if (msg.skipped.length) {
  tail += ' | skipped: ' + msg.skipped.join('; ');
}
var sizes = TABLE + ' ' + rows.length + ' rows from ' +
  msg.itemCount + ' item(s)';

function logOnly(text) {
  var line = {
    topic: 'log',
    payload: msg.day + ' [' + msg.mode + '] ' + text
  };
  return [null, line];
}

if (msg.failed.length) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: 'FAILED, nothing written'
  });
  return logOnly(
    'FAILED, NOTHING WRITTEN: ' + msg.failed.join(' | ') + tail
  );
}
if (!rows.length) {
  node.status({
    fill: 'grey',
    shape: 'ring',
    text: 'nothing to write'
  });
  return logOnly('NOTHING TO WRITE: ' + sizes + tail);
}
if (cfg.dryRun[TABLE]) {
  node.status({
    fill: 'yellow',
    shape: 'dot',
    text: 'dry run ' + rows.length
  });
  var firstRows = JSON.stringify(rows.slice(0, 2));
  return logOnly('DRY RUN: ' + sizes + '. First rows: ' + firstRows + tail);
}

node.status({
  fill: 'green',
  shape: 'dot',
  text: 'writing ' + rows.length
});
var writing = {
  topic: 'log',
  payload: msg.day + ' [' + msg.mode + '] WRITING ' + sizes + tail
};
msg.payload = rows;
delete msg.rows;
return [msg, writing];

// Sets the file path in the data lake.
// In: the output of the parquet node (msg.payload is passed on unchanged).
// Out: the same message with msg.path and msg.filename. The file name is
// fixed, so every run replaces the file and never duplicates it.
var cfg = flow.get('cfg');
msg.path = cfg.paths['pbi_machine_names'];
msg.filename = msg.path.split('/').pop();
return msg;

// Sets the folder of the shift patterns file for the list objects node.
// In: the shift names job. Out: msg.site, msg.what and msg.path = the folder.
// The file has no site column, so it lives in the folder site=All.
var TYPE_FOLDER = 'shift_naming';
var SITE = 'All';
var cfg = flow.get('cfg');

msg.site = SITE;
msg.what = 'shift patterns';
msg.path = cfg.referenceFolder + '/' + TYPE_FOLDER;
msg.path += '/site=' + SITE + '/';
return msg;

// Picks the newest .csv of the folder list (list objects).
// Out 1: msg.path for the read node, without data/ten=<tenant>/ or a leading
// slash. Out 2: a failed item when the folder has no .csv.
var TENANT_PREFIX = /^\/?(data\/ten=[^\/]+\/)?/;
var items = Array.isArray(msg.payload) ? msg.payload : [];
var files = items.filter(function (item) {
  return /\.csv$/i.test(item.key);
});

if (!files.length) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: 'no csv file for ' + msg.site
  });
  msg.payload = {
    name: msg.site,
    failed: msg.what + ' ' + msg.site + ': no csv file in ' + msg.path,
    skipped: null,
    rows: []
  };
  return [null, msg];
}

files.sort(function (a, b) {
  return String(b.lastModified).localeCompare(String(a.lastModified));
});
msg.path = String(files[0].key).replace(TENANT_PREFIX, '');
node.status({
  fill: 'green',
  shape: 'dot',
  text: msg.path.slice(-40)
});
return [msg, null];

// Builds the shift rows from the Shift Patterns file.
// In: msg.payload = the parsed rows (ShiftName, Shift).
// Out: msg.payload = an item {name, failed, skipped, rows}: one row per line
// of the file; the distinct step after the collect keeps each shift once.
var item = {
  name: 'shift patterns',
  failed: null,
  skipped: null,
  rows: []
};
var rows = Array.isArray(msg.payload) ? msg.payload : [];
if (!rows.length || rows[0].Shift === undefined) {
  item.failed = 'shift patterns: no Shift column or rows';
  msg.payload = item;
  return msg;
}

rows.forEach(function (row) {
  var shift = String(row.Shift === undefined ? '' : row.Shift).trim();
  if (shift) {
    item.rows.push({
      shift: shift,
      loaded_at: msg.loadedAt
    });
  }
});
msg.payload = item;
return msg;

// Collects the items that the join delivered into one list of rows.
// In: msg.payload = array of items {name, failed, skipped, rows}.
// Out: msg.rows, msg.failed and msg.skipped (lists), msg.itemCount.
var items = Array.isArray(msg.payload) ? msg.payload : [msg.payload];
var rows = [];
var failed = [];
var skipped = (msg.planSkipped || []).slice();

items.forEach(function (item) {
  if (!item) {
    return;
  }
  if (item.failed) {
    failed.push(item.failed);
  }
  if (item.skipped) {
    skipped.push(item.skipped);
  }
  rows = rows.concat(item.rows || []);
});
msg.rows = rows;
msg.failed = failed;
msg.skipped = skipped;
msg.itemCount = items.length;
delete msg.payload;
return msg;

// Keeps every shift name once.
// In: msg.rows = the shift rows of all calendars (names repeat).
// Out: msg.rows = the distinct shift names, in the order first seen.
var seen = {};
msg.rows = msg.rows.filter(function (row) {
  if (seen[row.shift]) {
    return false;
  }
  seen[row.shift] = true;
  return true;
});
return msg;

// Decides what happens with the table pbi_shift_naming.
// In: msg.rows, msg.failed, msg.skipped. Out 1: msg.payload = rows for the
// parquet node. Out 2: a log line. A failed item means nothing is written.
var TABLE = 'pbi_shift_naming';
var cfg = flow.get('cfg');
var rows = msg.rows;
var tail = '';
if (msg.skipped.length) {
  tail += ' | skipped: ' + msg.skipped.join('; ');
}
var sizes = TABLE + ' ' + rows.length + ' rows from ' +
  msg.itemCount + ' item(s)';

function logOnly(text) {
  var line = {
    topic: 'log',
    payload: msg.day + ' [' + msg.mode + '] ' + text
  };
  return [null, line];
}

if (msg.failed.length) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: 'FAILED, nothing written'
  });
  return logOnly(
    'FAILED, NOTHING WRITTEN: ' + msg.failed.join(' | ') + tail
  );
}
if (!rows.length) {
  node.status({
    fill: 'grey',
    shape: 'ring',
    text: 'nothing to write'
  });
  return logOnly('NOTHING TO WRITE: ' + sizes + tail);
}
if (cfg.dryRun[TABLE]) {
  node.status({
    fill: 'yellow',
    shape: 'dot',
    text: 'dry run ' + rows.length
  });
  var firstRows = JSON.stringify(rows.slice(0, 2));
  return logOnly('DRY RUN: ' + sizes + '. First rows: ' + firstRows + tail);
}

node.status({
  fill: 'green',
  shape: 'dot',
  text: 'writing ' + rows.length
});
var writing = {
  topic: 'log',
  payload: msg.day + ' [' + msg.mode + '] WRITING ' + sizes + tail
};
msg.payload = rows;
delete msg.rows;
return [msg, writing];

// Sets the file path in the data lake.
// In: the output of the parquet node (msg.payload is passed on unchanged).
// Out: the same message with msg.path and msg.filename. The file name is
// fixed, so every run replaces the file and never duplicates it.
var cfg = flow.get('cfg');
msg.path = cfg.paths['pbi_shift_naming'];
msg.filename = msg.path.split('/').pop();
return msg;

// Builds the pbi_calendar table: one row per date, Monday week start, week
// number like the report (DAX WEEKNUM(date, 2): week 1 holds 1 January).
// Out 1: msg.payload = the rows (topic pbi_calendar). Out 2: a log line.
var DAY_MS = 86400000;
var cfg = flow.get('cfg');
var MONTHS = [
  'January',
  'February',
  'March',
  'April',
  'May',
  'June',
  'July',
  'August',
  'September',
  'October',
  'November',
  'December'
];

function pad(n) {
  return n < 10 ? '0' + n : String(n);
}

// Week number as DAX WEEKNUM(date, 2): weeks start on Monday and the week
// that holds 1 January of the year is week 1 (not the ISO week number).
function weekNumber(ms) {
  var year = new Date(ms).getUTCFullYear();
  var jan1 = Date.UTC(year, 0, 1);
  var jan1Offset = (new Date(jan1).getUTCDay() + 6) % 7;
  var dayOfYear = Math.round((ms - jan1) / DAY_MS);
  return Math.floor((dayOfYear + jan1Offset) / 7) + 1;
}

var rows = [];
var start = Date.parse(cfg.calendarStart + 'T00:00:00Z');
var end = Date.parse(cfg.calendarEnd + 'T00:00:00Z');
for (var t = start; t <= end; t += DAY_MS) {
  var d = new Date(t);
  var month = d.getUTCMonth();
  var year = d.getUTCFullYear();
  var quarter = Math.floor(month / 3) + 1;
  var mondayOffset = (d.getUTCDay() + 6) % 7;
  rows.push({
    date: d.toISOString().slice(0, 10),
    year: year,
    month_number: month + 1,
    month: MONTHS[month],
    month_short_name: MONTHS[month].slice(0, 3),
    month_year: MONTHS[month].slice(0, 3) + ' ' + year,
    month_year_number: pad(month + 1) + ' ' + String(year).slice(2),
    quarter: 'QTR' + quarter,
    quarter_number: quarter,
    week_number: weekNumber(t),
    week_start: new Date(t - mondayOffset * DAY_MS).toISOString().slice(0, 10)
  });
}

var text = 'pbi_calendar ' + rows.length + ' rows';
if (cfg.dryRun.pbi_calendar) {
  var line = {
    topic: 'log',
    payload: 'calendar [setup] DRY RUN: ' + text
  };
  return [null, line];
}
var table = {
  topic: 'pbi_calendar',
  day: '',
  payload: rows
};
return [table, null];

// Sets the file path in the data lake.
// In: the output of the parquet node (msg.payload is passed on unchanged).
// Out: the same message with msg.path and msg.filename. The file name is
// fixed, so every run replaces the file and never duplicates it.
var cfg = flow.get('cfg');
msg.path = cfg.paths['pbi_calendar'];
msg.filename = msg.path.split('/').pop();
return msg;

// Sets the Glidepaths folder of one site for the list objects node.
// In: msg.payload = one site name (after the split). Out: msg.site, msg.what
// and msg.path = the reference folder of the site, ending with a slash.
var cfg = flow.get('cfg');

msg.site = msg.payload;
msg.what = 'glidepaths';
msg.path = cfg.referenceFolder + '/glidepaths/site=' + msg.site + '/';
return msg;

// Picks the newest .csv of the folder list (list objects).
// Out 1: msg.path for the read node, without data/ten=<tenant>/ or a leading
// slash. Out 2: a failed item when the folder has no .csv.
var TENANT_PREFIX = /^\/?(data\/ten=[^\/]+\/)?/;
var items = Array.isArray(msg.payload) ? msg.payload : [];
var files = items.filter(function (item) {
  return /\.csv$/i.test(item.key);
});

if (!files.length) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: 'no csv file for ' + msg.site
  });
  msg.payload = {
    name: msg.site,
    failed: msg.what + ' ' + msg.site + ': no csv file in ' + msg.path,
    skipped: null,
    rows: []
  };
  return [null, msg];
}

files.sort(function (a, b) {
  return String(b.lastModified).localeCompare(String(a.lastModified));
});
msg.path = String(files[0].key).replace(TENANT_PREFIX, '');
node.status({
  fill: 'green',
  shape: 'dot',
  text: msg.path.slice(-40)
});
return [msg, null];

// Builds the target lookup of one site from its Glidepaths file.
// In: msg.payload = parsed rows (Site Name, Line, OEE Bucket, month columns).
// Stores flow context targets_<site>: machine-site -> month 01/MM/YYYY ->
// {oee, pdt, updt, b: {bucket: value}}. Out 2: a failed item for an empty file.
var BUCKETS = {
  '% OEE': 'oee',
  'Planned Downtime (Total)': 'pdt',
  'Unplanned Downtime (Total)': 'updt'
};
// The file starts with a byte order mark: it sits in the first column name.
function clean(row) {
  var out = {};
  Object.keys(row).forEach(function (column) {
    out[column.replace(/\uFEFF/g, '')] = row[column];
  });
  return out;
}

var rows = Array.isArray(msg.payload) ? msg.payload.map(clean) : [];
if (!rows.length || rows[0].Line === undefined) {
  msg.payload = {
    failed: 'glidepaths ' + msg.site + ': no Line column or rows'
  };
  return [null, msg];
}

var lookup = {};
var cells = 0;
rows.forEach(function (row) {
  var field = BUCKETS[row['OEE Bucket']];
  var key = row.Line + '-' + row['Site Name'];
  Object.keys(row).forEach(function (column) {
    var value = String(row[column]).trim();
    if (!/^\d{2}\/\d{2}\/\d{4}$/.test(column) || value === '') {
      return;
    }
    var number = Number(value);
    if (isNaN(number)) {
      return;
    }
    lookup[key] = lookup[key] || {};
    lookup[key][column] = lookup[key][column] || {};
    lookup[key][column].b = lookup[key][column].b || {};
    lookup[key][column].b[row['OEE Bucket']] = number;
    if (field) {
      lookup[key][column][field] = number;
    }
    cells++;
  });
});
flow.set('targets_' + msg.site, lookup);
node.status({
  fill: 'green',
  shape: 'dot',
  text: msg.site + ': ' + cells + ' target values'
});
msg.payload = msg.site;
return [msg, null];

// Sets the folder of the Shift Patterns file for the list objects node.
// In: the message of one site (msg.site stays). Out: msg.what and msg.path =
// eu_report/reference/shift_naming/site=All/, the file of all sites.
var cfg = flow.get('cfg');

msg.what = 'shift patterns';
msg.path = cfg.referenceFolder + '/shift_naming/site=All/';
return msg;

// Picks the newest .csv of the folder list (list objects).
// Out 1: msg.path for the read node, without data/ten=<tenant>/ or a leading
// slash. Out 2: a failed item when the folder has no .csv.
var TENANT_PREFIX = /^\/?(data\/ten=[^\/]+\/)?/;
var items = Array.isArray(msg.payload) ? msg.payload : [];
var files = items.filter(function (item) {
  return /\.csv$/i.test(item.key);
});

if (!files.length) {
  node.status({
    fill: 'red',
    shape: 'ring',
